-   [68.3% obs. are in +-1 SD;]{.fragment fragment-index="3"}
-   [95.4% obs. are in +-2 SD;]{.fragment fragment-index="4"}
-   [99.7% obs. are in +-3 SD;]{.fragment fragment-index="4"}
:::

